// One-time initial-password reveal (Issue #5559). The password was generated by the
// controller for an account a cfg declared (credentials package, Issue #5555) and is
// held only by the secrets provider. An admin reads it once: the record moves pending
// to revealing, the secret is read and deleted, then the record is marked revealed. A
// response lost after that point loses the password for good — the admin deletes the
// account and has it recreated; there is no second read and no reset.

// credentialIDPattern is the shape of a record id (128 random bits, hex).
var credentialIDPattern = regexp.MustCompile(`^[0-9a-f]{32}$`)

type directoryCredentialItem struct {
	ID         string    `json:"id"`
	ResourceID string    `json:"resource_id"`
	CreatedAt  time.Time `json:"created_at"`
	ExpiresAt  time.Time `json:"expires_at"`
}

type directoryCredentialReveal struct {
	ID         string `json:"id"`
	ResourceID string `json:"resource_id"`
	Password   string `json:"password"`
}

func (s *Server) credentialNowFn() time.Time {
	if s.credentialClock != nil {
		return s.credentialClock()
	}
	return time.Now()
}

func (s *Server) credentialStoreOrUnavailable(w http.ResponseWriter) credentials.CredentialStore {
	s.mu.RLock()
	store := s.credentialStore
	s.mu.RUnlock()
	if store == nil {
		s.writeErrorResponse(w, http.StatusServiceUnavailable, "credential store unavailable", "SERVICE_UNAVAILABLE")
	}
	return store
}

// handleListDirectoryCredentials serves GET /api/v1/directory/credentials: the
// caller tenant's pending, unexpired records. A value is never part of the response.
func (s *Server) handleListDirectoryCredentials(w http.ResponseWriter, r *http.Request) {
	store := s.credentialStoreOrUnavailable(w)
	if store == nil {
		return
	}
	tenant, ok := callerOwnTenant(r.Context())
	if !ok {
		s.writeErrorResponse(w, http.StatusForbidden, "No tenant scope", "NO_TENANT_SCOPE")
		return
	}
	recs, err := store.List(r.Context(), credentials.Filter{TenantID: tenant, State: credentials.StatePending})
	if err != nil {
		s.logger.Error("credential list failed", "error", logging.SanitizeLogValue(err.Error()))
		s.writeErrorResponse(w, http.StatusInternalServerError, "credential list failed", "INTERNAL_ERROR")
		return
	}
	now := s.credentialNowFn()
	items := make([]directoryCredentialItem, 0, len(recs))
	for _, rec := range recs {
		if rec.TenantID != tenant || rec.State != credentials.StatePending || !now.Before(rec.ExpiresAt) {
			continue
		}
		items = append(items, directoryCredentialItem{ID: rec.ID, ResourceID: rec.ResourceID, CreatedAt: rec.CreatedAt, ExpiresAt: rec.ExpiresAt})
	}
	sort.Slice(items, func(i, j int) bool {
		if !items[i].CreatedAt.Equal(items[j].CreatedAt) {
			return items[i].CreatedAt.Before(items[j].CreatedAt)
		}
		return items[i].ID < items[j].ID
	})
	writeEntityJSON(w, map[string]interface{}{"items": items})
}

// revealAudit emits the audit event for one reveal attempt. The resource id is the
// cfg-declared id; the secret is never a detail.
func (s *Server) revealAudit(r *http.Request, principal *Principal, tenant, resourceID, recordID string, result business.AuditResult, reason string) {
	if resourceID == "" {
		resourceID = "unknown"
	}
	severity := business.AuditSeverityHigh
	if result == business.AuditResultSuccess {
		severity = business.AuditSeverityCritical
	}
	s.emitOperatorAudit(r, principal, auditTenantOrSystem(tenant), business.AuditEventSecurityEvent,
		"credential.reveal", "credential", resourceID, result, severity,
		map[string]interface{}{"record_id": logging.SanitizeLogValue(recordID), "reason": reason})
}

// findCredentialRecord locates a record by id across tenants. The caller authorises
// the record's tenant before using it.
func findCredentialRecord(ctx context.Context, store credentials.CredentialStore, id string) (*credentials.Record, error) {
	recs, err := store.List(ctx, credentials.Filter{})
	if err != nil {
		return nil, err
	}
	for _, rec := range recs {
		if rec.ID == id {
			return rec, nil
		}
	}
	return nil, credentials.ErrNotFound
}

// handleRevealDirectoryCredential serves POST /api/v1/directory/credentials/{id}/reveal.
func (s *Server) handleRevealDirectoryCredential(w http.ResponseWriter, r *http.Request) {
	store := s.credentialStoreOrUnavailable(w)
	if store == nil {
		return
	}
	ctx := r.Context()
	principal, _ := ctx.Value(principalContextKey).(*Principal)
	callerTenant, _ := callerOwnTenant(ctx)
	id := mux.Vars(r)["id"]

	notFound := func(tenant, resourceID, reason string, result business.AuditResult) {
		s.revealAudit(r, principal, tenant, resourceID, id, result, reason)
		s.writeErrorResponse(w, http.StatusNotFound, "credential not found", "NOT_FOUND")
	}
	if !credentialIDPattern.MatchString(id) {
		notFound(callerTenant, "", "invalid id", business.AuditResultFailure)
		return
	}
	rec, err := findCredentialRecord(ctx, store, id)
	if errors.Is(err, credentials.ErrNotFound) {
		notFound(callerTenant, "", "no such record", business.AuditResultFailure)
		return
	}
	if err != nil {
		s.revealFailed(w, r, principal, callerTenant, "", id, err)
		return
	}

	// Tenant authorisation precedes every read or write of the record's state.
	switch s.authorizeTenantAccess(ctx, principal, rec.TenantID) {
	case tenantAuthAllowed:
	case tenantAuthNeedsCrossing:
		s.revealAudit(r, principal, rec.TenantID, rec.ResourceID, id, business.AuditResultDenied, "tenant crossing required")
		s.writeTenantCrossingChallenge(w, rec.TenantID)
		return
	default:
		notFound(rec.TenantID, rec.ResourceID, "tenant access denied", business.AuditResultDenied)
		return
	}

	pw, status, err := s.revealPassword(ctx, store, rec)
	switch {
	case err != nil:
		s.revealFailed(w, r, principal, rec.TenantID, rec.ResourceID, id, err)
	case status != 0:
		s.revealRefused(w, r, principal, rec, status)
	default:
		s.revealAudit(r, principal, rec.TenantID, rec.ResourceID, id, business.AuditResultSuccess, "revealed")
		writeEntityJSON(w, directoryCredentialReveal{ID: rec.ID, ResourceID: rec.ResourceID, Password: pw})
	}
}

// Refusals revealPassword reports without an error.
const (
	revealGone       = http.StatusGone
	revealInProgress = http.StatusConflict
)

func (s *Server) revealRefused(w http.ResponseWriter, r *http.Request, principal *Principal, rec *credentials.Record, status int) {
	if status == revealInProgress {
		s.revealAudit(r, principal, rec.TenantID, rec.ResourceID, rec.ID, business.AuditResultFailure, "reveal in progress")
		s.writeErrorResponse(w, http.StatusConflict, "a reveal of this credential is in progress; retry shortly", "REVEAL_IN_PROGRESS")
		return
	}
	s.revealAudit(r, principal, rec.TenantID, rec.ResourceID, rec.ID, business.AuditResultFailure, "already revealed, expired or gone")
	s.writeErrorResponse(w, http.StatusGone, "credential is no longer available", "CREDENTIAL_GONE")
}

func (s *Server) revealFailed(w http.ResponseWriter, r *http.Request, principal *Principal, tenant, resourceID, id string, err error) {
	s.revealAudit(r, principal, tenant, resourceID, id, business.AuditResultError, "reveal failed")
	if errors.Is(err, credentials.ErrNotClusterAtomic) {
		s.writeErrorResponse(w, http.StatusServiceUnavailable, "credential reveal is unavailable: the config store is not cluster-atomic", "CLUSTER_NOT_ATOMIC")
		return
	}
	if errors.Is(err, credentials.ErrConflict) {
		s.writeErrorResponse(w, http.StatusConflict, "credential changed concurrently; retry", "CONFLICT")
		return
	}
	s.logger.Error("credential reveal failed", "error", logging.SanitizeLogValue(err.Error()))
	s.writeErrorResponse(w, http.StatusInternalServerError, "credential reveal failed", "INTERNAL_ERROR")
}

// revealPassword runs the state machine. It returns the password, or a non-zero
// refusal status (revealGone / revealInProgress), or an error. The password is
// returned only after the secret has been deleted.
func (s *Server) revealPassword(ctx context.Context, store credentials.CredentialStore, rec *credentials.Record) (string, int, error) {
	key := rec.Key()
	cur, err := store.Get(ctx, key) // also fails closed on a non-atomic clustered store
	if errors.Is(err, credentials.ErrNotFound) {
		return "", revealGone, nil
	}
	if err != nil {
		return "", 0, err
	}
	if cur.ID != rec.ID {
		return "", revealGone, nil
	}
	now := s.credentialNowFn()
	switch cur.State {
	case credentials.StateRevealed, credentials.StateExpired:
		return "", revealGone, nil
	case credentials.StateRevealing:
		if cur.Password == "" {
			// The secret is gone: an earlier reveal finished deleting it. Settle the record.
			_, _ = store.Claim(ctx, key, rec.ID, credentials.StateRevealing, credentials.StateRevealed)
			return "", revealGone, nil
		}
		if now.Sub(cur.StateChangedAt) < credentials.RevealStaleAfter {
			return "", revealInProgress, nil
		}
		// Stale with the secret still present: the earlier reveal crashed before deleting it.
		// A record past its expiry stays unrevealable on this path too.
		if !now.Before(cur.ExpiresAt) {
			return "", revealGone, nil
		}
		if _, err := store.Claim(ctx, key, rec.ID, credentials.StateRevealing, credentials.StatePending); err != nil {
			return "", 0, err
		}
	case credentials.StatePending:
		if !now.Before(cur.ExpiresAt) || cur.Password == "" {
			return "", revealGone, nil
		}
	default:
		return "", revealGone, nil
	}

	if _, err := store.Claim(ctx, key, rec.ID, credentials.StatePending, credentials.StateRevealing); err != nil {
		return "", 0, err
	}
	claimed, err := store.Get(ctx, key)
	if err != nil {
		return "", 0, err
	}
	if claimed.ID != rec.ID || claimed.Password == "" {
		_, _ = store.Claim(ctx, key, rec.ID, credentials.StateRevealing, credentials.StateRevealed)
		return "", revealGone, nil
	}
	// Delete before answering: if the delete fails nothing was disclosed, and the record
	// becomes claimable again after RevealStaleAfter.
	if err := store.DeleteSecret(ctx, &claimed.Record); err != nil {
		return "", 0, err
	}
	if _, err := store.Claim(ctx, key, rec.ID, credentials.StateRevealing, credentials.StateRevealed); err != nil {
		// The secret is already gone, so the record can only ever answer 410 from here.
		s.logger.Warn("credential revealed but record not settled",
			"record_id", logging.SanitizeLogValue(rec.ID), "error", logging.SanitizeLogValue(err.Error()))
	}
	return claimed.Password, 0, nil
}
